<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    background: #1a1a2e;
    color: #e0e0e0;
    font-family: 'Segoe UI', system-ui, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    overflow: hidden;
  }

  .container {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
  }

  h1 {
    font-size: 2rem;
    letter-spacing: 4px;
    text-transform: uppercase;
    color: #00ff88;
    text-shadow: 0 0 20px rgba(0, 255, 136, 0.4);
  }

  #score {
    font-size: 1.4rem;
    background: #16213e;
    padding: 8px 24px;
    border-radius: 8px;
    border: 1px solid #0f3460;
    min-width: 160px;
    text-align: center;
  }

  #score span {
    color: #00ff88;
    font-weight: bold;
    font-size: 1.5rem;
  }

  canvas {
    border: 2px solid #0f3460;
    border-radius: 4px;
    box-shadow: 0 0 30px rgba(0, 255, 136, 0.1), inset 0 0 60px rgba(0,0,0,0.3);
    background: #0a0a1a;
  }

  .controls {
    display: flex;
    gap: 12px;
  }

  button {
    padding: 10px 28px;
    font-size: 1rem;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
    letter-spacing: 1px;
    transition: all 0.2s ease;
  }

  #start {
    background: linear-gradient(135deg, #00ff88, #00cc6a);
    color: #1a1a2e;
  }
  #start:hover { transform: translateY(-2px); box-shadow: 0 4px 16px rgba(0,255,136,0.4); }

  #pause {
    background: linear-gradient(135deg, #ffd700, #ffaa00);
    color: #1a1a2e;
  }
  #pause:hover { transform: translateY(-2px); box-shadow: 0 4px 16px rgba(255,215,0,0.4); }

  #reset {
    background: linear-gradient(135deg, #e94560, #c0392b);
    color: #fff;
  }
  #reset:hover { transform: translateY(-2px); box-shadow: 0 4px 16px rgba(233,69,96,0.4); }

  button:active { transform: translateY(0) scale(0.97); }

  .status {
    font-size: 0.95rem;
    color: #888;
    height: 1.2em;
  }
</style>
</head>
<body>
<div class="container">
  <h1>🐍 Snake</h1>
  <div id="score">Score: <span id="score-val">0</span></div>
  <canvas id="snake" width="400" height="400"></canvas>
  <div class="controls">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
  </div>
  <div class="status" id="status">Press Start to play!</div>
</div>

<script>
(function() {
  "use strict";

  const canvas = document.getElementById("snake");
  const ctx = canvas.getContext("2d");
  const scoreEl = document.getElementById("score-val");
  const statusEl = document.getElementById("status");

  // Grid config
  const CELL = 20;          // pixels per cell
  const w = 20;             // columns (cells)
  const h = 20;             // rows (cells)

  let snakeArr, direction, nextDirection, foodPos, scoreVal, aliveFlag, running, paused, gameOver;
  let tickInterval = null;
  const TICK_MS = 120;      // ms per tick

  function init() {
    snakeArr = [[9, 0], [8, 0], [7, 0]];   // head first, length 3 moving right
    direction = "right";
    nextDirection = "right";
    scoreVal = 0;
    aliveFlag = true;
    gameOver = false;
    paused = false;
    running = false;
    placeFood();
    updateUI();
  }

  function placeFood() {
    const occupied = new Set(snakeArr.map(s => s[0] + "," + s[1]));
    let fx, fy;
    do {
      fx = Math.floor(Math.random() * w);
      fy = Math.floor(Math.random() * h);
    } while (occupied.has(fx + "," + fy));
    foodPos = [fx, fy];
  }

  function updateUI() {
    scoreEl.textContent = scoreVal;
    if (gameOver) statusEl.textContent = "Game Over! Press Reset.";
    else if (paused) statusEl.textContent = "Paused";
    else if (!running) statusEl.textContent = "Press Start to play!";
    else statusEl.textContent = "Use arrow keys to steer.";
  }

  // --- Drawing ---
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Grid lines (subtle)
    ctx.strokeStyle = "rgba(255,255,255,0.03)";
    ctx.lineWidth = 1;
    for (let x = 0; x <= w; x++) {
      ctx.beginPath(); ctx.moveTo(x * CELL, 0); ctx.lineTo(x * CELL, h * CELL); ctx.stroke();
    }
    for (let y = 0; y <= h; y++) {
      ctx.beginPath(); ctx.moveTo(0, y * CELL); ctx.lineTo(w * CELL, y * CELL); ctx.stroke();
    }

    // Food with glow
    const fx = foodPos[0] * CELL + CELL / 2;
    const fy = foodPos[1] * CELL + CELL / 2;
    ctx.shadowColor = "#ff4444";
    ctx.shadowBlur = 15;
    ctx.fillStyle = "#ff3b3b";
    ctx.beginPath();
    ctx.arc(fx, fy, CELL / 2 - 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.shadowBlur = 0;

    // Snake body (tail first to draw head on top)
    for (let i = snakeArr.length - 1; i >= 0; i--) {
      const seg = snakeArr[i];
      const x = seg[0] * CELL;
      const y = seg[1] * CELL;

      if (i === 0) {
        // Head
        ctx.shadowColor = "#00ff88";
        ctx.shadowBlur = 12;
        ctx.fillStyle = "#00ff88";
        roundRect(ctx, x + 1, y + 1, CELL - 2, CELL - 2, 5);
        ctx.fill();
        ctx.shadowBlur = 0;

        // Eyes
        drawEyes(seg[0], seg[1]);
      } else {
        // Body gradient from bright to darker green
        const t = i / snakeArr.length;
        const g = Math.floor(255 - t * 130);
        ctx.fillStyle = `rgb(0, ${g}, ${Math.floor(g * 0.4)})`;
        roundRect(ctx, x + 1.5, y + 1.5, CELL - 3, CELL - 3, 4);
        ctx.fill();
      }
    }

    // Game over overlay
    if (gameOver) {
      ctx.fillStyle = "rgba(0,0,0,0.6)";
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = "#ff3b3b";
      ctx.font = "bold 48px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText("GAME OVER", canvas.width / 2, canvas.height / 2 - 10);
      ctx.fillStyle = "#ccc";
      ctx.font = "20px sans-serif";
      ctx.fillText("Score: " + scoreVal, canvas.width / 2, canvas.height / 2 + 30);
    }
  }

  function roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function drawEyes(hx, hy) {
    const cx = hx * CELL + CELL / 2;
    const cy = hy * CELL + CELL / 2;
    let e1, e2;
    const off = 4;
    switch (direction) {
      case "up":    e1 = [cx - off, cy - off]; e2 = [cx + off, cy - off]; break;
      case "down":  e1 = [cx - off, cy + off]; e2 = [cx + off, cy + off]; break;
      case "left":  e1 = [cx - off, cy - off]; e2 = [cx - off, cy + off]; break;
      case "right": e1 = [cx + off, cy - off]; e2 = [cx + off, cy + off]; break;
    }
    ctx.fillStyle = "#fff";
    ctx.beginPath(); ctx.arc(e1[0], e1[1], 3, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(e2[0], e2[1], 3, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = "#1a1a2e";
    ctx.beginPath(); ctx.arc(e1[0], e1[1], 1.5, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(e2[0], e2[1], 1.5, 0, Math.PI * 2); ctx.fill();
  }

  // --- Game logic ---
  function tick() {
    if (!aliveFlag || paused) return;

    direction = nextDirection;

    const head = snakeArr[0];
    let nx = head[0], ny = head[1];
    switch (direction) {
      case "up":    ny--; break;
      case "down":  ny++; break;
      case "left":  nx--; break;
      case "right": nx++; break;
    }

    // Wall collision
    if (nx < 0 || nx >= w || ny < 0 || ny >= h) {
      aliveFlag = false;
      gameOver = true;
      running = false;
      stopLoop();
      updateUI();
      draw();
      return;
    }

    // Self collision (check against all body segments except tail if not growing)
    const ateFood = (nx === foodPos[0] && ny === foodPos[1]);
    const checkLen = ateFood ? snakeArr.length : snakeArr.length - 1;
    for (let i = 0; i < checkLen; i++) {
      if (snakeArr[i][0] === nx && snakeArr[i][1] === ny) {
        aliveFlag = false;
        gameOver = true;
        running = false;
        stopLoop();
        updateUI();
        draw();
        return;
      }
    }

    // Move: prepend new head
    snakeArr.unshift([nx, ny]);

    if (ateFood) {
      scoreVal++;
      placeFood();
    } else {
      snakeArr.pop();
    }

    updateUI();
    draw();
  }

  function startLoop() {
    stopLoop();
    running = true;
    paused = false;
    gameOver = false;
    statusEl.textContent = "Use arrow keys to steer.";
    tickInterval = setInterval(tick, TICK_MS);
    updateUI();
    draw();
  }

  function pauseLoop() {
    if (!running) return;
    paused = !paused;
    if (paused) {
      stopLoop();
    } else {
      startLoop();
    }
    updateUI();
  }

  function stopLoop() {
    if (tickInterval !== null) {
      clearInterval(tickInterval);
      tickInterval = null;
    }
  }

  // --- API ---
  window.game = {
    get w() { return w; },
    get h() { return h; },

    reset: function() {
      stopLoop();
      init();
      draw();
    },

    tick: function() {
      if (!aliveFlag) return;
      // force a single tick even when paused or not running, for grading
      const wasPaused = paused;
      paused = false;
      tick();
      paused = wasPaused;
    },

    setDir: function(dir) {
      const opposites = { up: "down", down: "up", left: "right", right: "left" };
      if (dir === opposites[direction]) return; // ignore 180° reversal
      nextDirection = dir;
    },

    setFood: function(x, y) {
      foodPos = [x, y];
      draw();
    },

    snake: function() {
      return snakeArr.map(s => [s[0], s[1]]);
    },

    food: function() {
      return [foodPos[0], foodPos[1]];
    },

    alive: function() {
      return !!aliveFlag;
    },

    score: function() {
      return scoreVal;
    }
  };

  // --- Input ---
  document.addEventListener("keydown", function(e) {
    const keyMap = {
      ArrowUp: "up", ArrowDown: "down", ArrowLeft: "left", ArrowRight: "right",
      w: "up", W: "up", s: "down", S: "down", a: "left", A: "left", d: "right", D: "right"
    };
    const dir = keyMap[e.key];
    if (dir) {
      e.preventDefault();
      window.game.setDir(dir);
    }
  });

  // --- Buttons ---
  document.getElementById("start").addEventListener("click", function() {
    startLoop();
  });

  document.getElementById("pause").addEventListener("click", function() {
    pauseLoop();
  });

  document.getElementById("reset").addEventListener("click", function() {
    window.game.reset();
  });

  // --- Init ---
  init();
  draw();
})();
</script>
</body>
</html>
